116: fn gf_mul(x: u8, y: u8) -> u8 {
117:     // multiplies two numbers in GF 2^8
118:     return ((y & 1) * x)
119:         ^ ((y >> 1 & 1) * xtime(x))
120:         ^ ((y >> 2 & 1) * xtime(xtime(x)))
121:         ^ ((y >> 3 & 1) * xtime(xtime(xtime(x))))
122:         ^ ((y >> 4 & 1) * xtime(xtime(xtime(xtime(x)))));
123: }
