29: impl BlockCipher for ShuffledAes {
30:     fn encrypt(&self, pt: [u8; 16]) -> [u8; 16] {
31:         let mut state = pt;
32: 
33:         xor(&mut state, &self.round_keys[0]);
34: 
35:         // sub bytes
36:         for key_idx in 1..NUMROUNDS + 1 {
37:             sub_bytes(&mut state);
38:             xor(&mut state, &self.round_keys[key_idx]);
39:         }
40: 
41:         // shift rows mix columns
42:         for key_idx in NUMROUNDS + 1..2 * NUMROUNDS + 1 {
43:             shift_rows(&mut state);
44:             mix_columns(&mut state);
45:             xor(&mut state, &self.round_keys[key_idx]);
46:         }
47: 
48:         return state;
49:     }
50: 
51:     fn decrypt(&self, ct: [u8; 16]) -> [u8; 16] {
52:         let mut state = ct;
53: 
54:         // shift rows mix columns
55:         for key_idx in (NUMROUNDS + 1..2 * NUMROUNDS + 1).rev() {
56:             xor(&mut state, &self.round_keys[key_idx]);
57:             inv_mix_columns(&mut state);
58:             inv_shift_rows(&mut state);
59:         }
60: 
61:         // sub bytes
62:         for key_idx in (1..NUMROUNDS + 1).rev() {
63:             xor(&mut state, &self.round_keys[key_idx]);
64:             inv_sub_bytes(&mut state);
65:         }
66: 
67:         xor(&mut state, &self.round_keys[0]);
68: 
69:         return state;
70:     }
